def temu_cross_parent_page(
    self,
    page_no=1,
    page_size=100,
    shop_ids=None,
    date_type="createDate",
    start_date=None,
    end_date=None,
):
    """Temu 跨境店在线产品（父体）分页。
    POST /api/multiplatform/temu/product/getParentPageList.json
    实调要求 startDate 非空；默认 createDate + 宽时间窗拉全量。
    返回 data: { pageNo, pageSize, totalPage, totalSize, rows[] }
    父体关键字段（文档）：parentId, shopId, skcId, productName, selectStatus, trusteeship ...
    """
    body = {
        "pageNo": int(page_no),
        "pageSize": int(page_size),
        "dateType": date_type or "createDate",
        "startDate": start_date or "2020-01-01",
        "endDate": end_date,  # 下面补今天
    }
    if not body["endDate"]:
        import time as _time

        body["endDate"] = _time.strftime("%Y-%m-%d")
    if shop_ids:
        body["shopIdList"] = [str(s) for s in shop_ids]
    return self.post(
        "/api/multiplatform/temu/product/getParentPageList.json", body
    )

