5	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun false
6	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -ListOnly
7	#
8	# Requires: Ziniao client running + ziniao-cli doctor OK
9	# Config: config\stores.config.json
10	
11	param(
12	  [string]$ConfigPath = "",
13	  [switch]$ListOnly,
14	  # string so -File callers work (Nullable[bool] cannot bind "$true"/"$false" from -File)
15	  # omit / empty => use config.options.dryRun; true|1|yes / false|0|no
16	  [string]$DryRun = ""
17	)
18	
19	$ErrorActionPreference = 'Stop'
20	# ziniao-cli writes progress to stderr; do not treat as terminating
21	$PSNativeCommandUseErrorActionPreference = $false
22	$root = Split-Path $PSScriptRoot -Parent
23	if (-not $ConfigPath) {
24	  $ConfigPath = Join-Path $root 'config\stores.config.json'
25	}
26	$scrapeJsPath = Join-Path $root 'scripts\scrape-ads-page.js'
27	$dateRangeJsPath = Join-Path $root 'scripts\set-date-range.js'
28	
29	if (-not (Test-Path $ConfigPath)) {
30	  throw "Missing config: $ConfigPath (copy config\stores.config.example.json)"
31	}
32	if (-not (Test-Path $scrapeJsPath)) {
33	  throw "Missing scrape script: $scrapeJsPath"
34	}
35	if (-not (Test-Path $dateRangeJsPath)) {
36	  throw "Missing date-range script: $dateRangeJsPath"
37	}
38	
39	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
40	$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
41	$dateRangeJsTemplate = Get-Content $dateRangeJsPath -Raw -Encoding UTF8
42	$analysisLib = Join-Path $PSScriptRoot 'daily-analysis.ps1'
43	if (Test-Path $analysisLib) { . $analysisLib }
44	$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
45	if (Test-Path $qingquanLib) { . $qingquanLib }
46	$ziniaoWinLib = Join-Path $PSScriptRoot 'ziniao-window.ps1'
47	if (-not (Test-Path $ziniaoWinLib)) { throw "Missing $ziniaoWinLib" }
48	. $ziniaoWinLib
49	
50	# Always create logs/ first so early failures (Bridge down, ListOnly, throw) still leave a file
51	$script:logsDir = Join-Path $root 'logs'
52	New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
53	$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
54	$script:runLogFile = Join-Path $script:logsDir ("multi-store-run-{0}.log" -f $script:runStamp)
55	$script:runMode = if ($ListOnly) { 'listOnly' } else { 'scrape' }
56	
57	function Write-RunLog([string]$msg) {
58	  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
59	  try {
60	    Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8
61	  } catch { }
62	}
63	
64	function Write-Step([string]$msg) {
65	  $line = "[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg
66	  Write-Host $line
67	  Write-RunLog $msg
68	}
69	
70	function Save-FailArtifact([string]$errorText, [hashtable]$extra = @{}) {
71	  $obj = [ordered]@{
72	    ok        = $false
73	    mode      = $script:runMode
74	    time      = (Get-Date).ToString('o')
75	    error     = $errorText
76	    runLog    = $script:runLogFile
77	    config    = $ConfigPath
78	    root      = $root
79	  }
80	  foreach ($k in $extra.Keys) { $obj[$k] = $extra[$k] }
81	  $failPath = Join-Path $script:logsDir ("multi-store-fail-{0}.json" -f $script:runStamp)
82	  try {
83	    ($obj | ConvertTo-Json -Depth 8) | Set-Content -LiteralPath $failPath -Encoding UTF8
84	    Write-Step ("fail log: {0}" -f $failPath)
85	  } catch {
86	    Write-Host ("[warn] could not write fail log: {0}" -f $_)
87	  }
88	  Write-Step ("run log: {0}" -f $script:runLogFile)
