$base = "E:\project\清泉跨境系统（企业级）"
# 字段映射字典
$f = Join-Path $base "docs\字段映射字典.md"
$c = Get-Content -LiteralPath $f -Raw -Encoding UTF8
$n = $c -replace '\|\s*\|\s*27328767468273\s*\|\s*Gardena\s*\|\s*Tiktok - KK Seagull\s*\|', '| | 27328767468273 | SHOP INOUT | Tiktok - KK Seagull |'
if ($n -ne $c) { Set-Content -LiteralPath $f -Value $n -Encoding UTF8 -NoNewline; Write-Host "UPD 字段映射字典" } else { Write-Host "NOMATCH 字段映射字典"; Select-String -LiteralPath $f -Pattern "27328767468273|Gardena|KK Seagull|INOUT" | ForEach-Object { $_.Line } }

# 数据库现状说明
$f2 = Join-Path $base "docs\数据库现状说明.md"
Select-String -LiteralPath $f2 -Pattern "27328767468273|Gardena|KK Seagull|INOUT" | ForEach-Object { "$($_.LineNumber):$($_.Line)" }

# seed_demo_tasks
$f3 = Join-Path $base "backend\app\scripts\seed_demo_tasks.py"
Select-String -LiteralPath $f3 -Pattern "27328767468273|Gardena|KK Seagull|INOUT" | ForEach-Object { "$($_.LineNumber):$($_.Line)" }

# remaining configs still Gardena?
Get-ChildItem -LiteralPath (Join-Path $base "collectors\tiktok-ads\config") -Filter "stores.config*.json" | ForEach-Object {
  $hits = Select-String -LiteralPath $_.FullName -Pattern 'KK Seagull.*=.*"Gardena"|KK Seagull":\s*"Gardena"'
  if ($hits) { Write-Host "STILL $($_.Name)" }
}
# verify map
Get-ChildItem -LiteralPath (Join-Path $base "collectors\tiktok-ads\config") -Filter "stores.config*.json" | ForEach-Object {
  $m = Select-String -LiteralPath $_.FullName -Pattern 'KK Seagull'
  if ($m) { Write-Host "$($_.Name): $($m.Line.Trim())" }
}

$base = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\config"
# uk-only Pop was wrongly mapped to Gardena
$f = Join-Path $base "stores.config.uk-only.json"
$c = Get-Content -LiteralPath $f -Raw -Encoding UTF8
$n = $c -replace '"TikTok - Pop"\s*:\s*"Gardena"', '"TikTok - Pop": "TikTok - Pop"'
if ($n -ne $c) { Set-Content -LiteralPath $f -Value $n -Encoding UTF8 -NoNewline; Write-Host "UPD uk-only Pop map" } else { Write-Host "SKIP uk-only" }

# gardena-only note about second store
$f2 = Join-Path $base "stores.config.gardena-only.json"
$c2 = Get-Content -LiteralPath $f2 -Raw -Encoding UTF8
$n2 = $c2 -replace 'Gardena 第二店复跑待做', 'SHOP INOUT（原误称 Gardena 配置）视频详情复跑待做；真·Gardena 紫鸟 storeId 待补'
if ($n2 -ne $c2) { Set-Content -LiteralPath $f2 -Value $n2 -Encoding UTF8 -NoNewline; Write-Host "UPD gardena-only note" }

# final verification
Write-Host "==== final KK/Gardena/INOUT ===="
Get-ChildItem -LiteralPath $base -Filter "stores.config*.json" | ForEach-Object {
  $hits = Select-String -LiteralPath $_.FullName -Pattern 'Gardena|KK Seagull|SHOP INOUT'
  foreach ($h in $hits) { Write-Host "$($_.Name):$($h.LineNumber): $($h.Line.Trim())" }
}
Write-Host "==== seed ===="
Select-String -LiteralPath "E:\project\清泉跨境系统（企业级）\backend\app\scripts\seed.py" -Pattern "tiktok" | ForEach-Object { $_.Line.Trim() }
Write-Host "==== 对照表 3.1 ===="
Select-String -LiteralPath "E:\project\清泉跨境系统（企业级）\docs\TK-赛狐数据源对照.md" -Pattern "INOUT|Gardena|KK Seagull|2732|HKGB|GBLC" | ForEach-Object { "$($_.LineNumber):$($_.Line.Trim())" }

$base = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\config"
$files = @(
  "stores.config.orders-page-test.json",
  "stores.config.pop-only.json",
  "stores.config.uk-orders-5p.json"
)
foreach ($name in $files) {
  $f = Join-Path $base $name
  $c = Get-Content -LiteralPath $f -Raw -Encoding UTF8
  $n = $c -replace '"TikTok - Pop"\s*:\s*"Gardena"', '"TikTok - Pop": "TikTok - Pop"'
  if ($n -ne $c) { Set-Content -LiteralPath $f -Value $n -Encoding UTF8 -NoNewline; Write-Host "UPD $name" } else { Write-Host "SKIP $name" }
}
Write-Host "==== remaining Gardena in storeNameMap ===="
Get-ChildItem -LiteralPath $base -Filter "stores.config*.json" | ForEach-Object {
  $hits = Select-String -LiteralPath $_.FullName -Pattern ':\s*"Gardena"'
  foreach ($h in $hits) { Write-Host "$($_.Name):$($h.LineNumber): $($h.Line.Trim())" }
}

$base = "E:\project\清泉跨境系统（企业级）"
Select-String -LiteralPath "$base\collectors\tiktok-ads\config\stores.config.json" -Pattern "Tiktok_Shop2|27501502216807|Deal to deal" | ForEach-Object { $_.Line.Trim() }
Select-String -LiteralPath "$base\backend\app\scripts\seed.py" -Pattern "tiktok" | ForEach-Object { $_.Line.Trim() }
Select-String -LiteralPath "$base\docs\TK-赛狐数据源对照.md" -Pattern "Deal to deal|Tiktok_Shop2|275015|GBLCJGQ" | ForEach-Object { "$($_.LineNumber):$($_.Line.Trim())" }
Select-String -LiteralPath "$base\docs\字段映射字典.md" -Pattern "Deal to deal|275015" | ForEach-Object { $_.Line.Trim() }

$base = "E:\project\清泉跨境系统（企业级）"
$cfgDir = Join-Path $base "collectors\tiktok-ads\config"

# 1) all stores.config*: TikTok - Pop -> Gardena in storeNameMap
Get-ChildItem -LiteralPath $cfgDir -Filter "stores.config*.json" | ForEach-Object {
  $c = Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8
  $n = $c -replace '"TikTok - Pop"\s*:\s*"TikTok - Pop"', '"TikTok - Pop": "Gardena"'
  # also handle if already Gardena
  if ($n -ne $c) {
    Set-Content -LiteralPath $_.FullName -Value $n -Encoding UTF8 -NoNewline
    Write-Host "UPD $($_.Name)"
  } else {
    $has = Select-String -LiteralPath $_.FullName -Pattern 'TikTok - Pop'
    if ($has) { Write-Host "CHK $($_.Name): $($has.Line.Trim())" } else { Write-Host "NO-POP $($_.Name)" }
  }
}

# example note
$ex = Join-Path $cfgDir "stores.config.example.json"
$c = Get-Content -LiteralPath $ex -Raw -Encoding UTF8
$oldNote = '业务确认\(2026-08-06）：Tiktok - KK Seagull / 27328767468273 = SHOP INOUT（勿再标成 Gardena）。Gardena 的紫鸟 storeId 待补。'
$newNote = '业务确认(2026-08-06)：Tiktok - KK Seagull / 27328767468273 = SHOP INOUT；TikTok - Pop / 27758103898326 = Gardena（赛狐 HKGBCB8LQLRC）。'
$n = $c -replace [regex]::Escape('业务确认(2026-08-06)：Tiktok - KK Seagull / 27328767468273 = SHOP INOUT（勿再标成 Gardena）。Gardena 的紫鸟 storeId 待补。'), $newNote
if ($n -eq $c) {
  # try looser
  $n = $c -replace '业务确认\(2026-08-06）[^"]+', $newNote
}
if ($n -ne $c) { Set-Content -LiteralPath $ex -Value $n -Encoding UTF8 -NoNewline; Write-Host "NOTE example" } else { Write-Host "NOTE skip"; Select-String -LiteralPath $ex -Pattern "_storeNameMap_note|Pop|Gardena" | ForEach-Object { $_.Line.Trim() } }

# verify maps
Write-Host "==== storeNameMap ===="
Get-ChildItem -LiteralPath $cfgDir -Filter "stores.config*.json" | ForEach-Object {
  $hits = Select-String -LiteralPath $_.FullName -Pattern 'KK Seagull|TikTok - Pop'
  foreach ($h in $hits) { if ($h.Line -match 'storeNameMap|Seagull|Pop') { Write-Host "$($_.Name): $($h.Line.Trim())" } }
}

